                        Value::string(piece, head),
                    );
                }
                idx += 1;
            }
            vec![Value::record(record, head)]
        } else {
            let mut record = Record::with_capacity(split_result.len());
            let mut idx = 0;
            let mut name_idx = 0;
            while idx < split_result.len() {
                let piece = split_result[idx];
                if name_idx < rest.len() {
                    let column_name = rest[name_idx].item.clone();
                    if column_name.is_empty() {
                        if piece.is_empty() {
                            record.push(column_name, Value::string(piece, head));
                        } else if piece.len() > 32 {
